from itertools import product

pairs = {')': '(', ']': '[', '}': '{'}
def _expected_balanced(text):
    stack = []
    for char in text:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack.pop() != pairs[char]:
                return False
    return not stack

for length in range(7):
    for chars in product('()[]{}', repeat=length):
        expression = ''.join(chars)
        assert check_expression(expression) is _expected_balanced(expression)
